-- Tenant consent is normal Auth, distinct from Controller owner administration.
-- All resources and policies in this service use an isolated, private namespace.
-- No existing bucket/Auth account/policy/secret is adopted or rewritten.
BEGIN;
CREATE TABLE public.sandy_supabase_tenant_consents(
 tenant_id uuid PRIMARY KEY REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 auth_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
 operations text[] NOT NULL DEFAULT ARRAY[]::text[], approved_emails text[] NOT NULL DEFAULT ARRAY[]::text[],
 allow_erasure boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL,
 revision integer NOT NULL DEFAULT 1 CHECK(revision>0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.sandy_supabase_tenant_controls(
 tenant_id uuid PRIMARY KEY REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 legal_hold boolean NOT NULL DEFAULT false,retention_until timestamptz,
 updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.sandy_supabase_managed_users(
 tenant_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 user_id uuid NOT NULL,source text NOT NULL CHECK(source IN('confirmed_portal_self','service_created')),
 creation_admission_id uuid REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,user_id),UNIQUE(user_id)
);
CREATE TABLE public.sandy_supabase_user_reservations(
 admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 tenant_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 normalized_email text NOT NULL,user_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.sandy_supabase_managed_buckets(
 tenant_id uuid PRIMARY KEY REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 bucket_id text NOT NULL UNIQUE,creation_admission_id uuid NOT NULL REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 state text NOT NULL CHECK(state IN('reserved','active','deleted')),bound_at timestamptz
);
CREATE TABLE public.sandy_supabase_managed_channels(
 tenant_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 name text NOT NULL CHECK(name ~ '^[a-z][a-z0-9_-]{0,63}$'),description text NOT NULL DEFAULT '',
 revision integer NOT NULL DEFAULT 1 CHECK(revision>0),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','deleted')),PRIMARY KEY(tenant_id,name)
);
CREATE TABLE public.sandy_supabase_managed_policies(
 tenant_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 kind text NOT NULL CHECK(kind IN('storage','realtime')),name text NOT NULL,
 provider_name text NOT NULL UNIQUE,subject_user_id uuid NOT NULL,command text NOT NULL,
 resource text NOT NULL,definition_sha256 text NOT NULL,PRIMARY KEY(tenant_id,kind,name)
);
CREATE TABLE public.sandy_supabase_managed_vault(
 tenant_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 name text NOT NULL,secret_id uuid NOT NULL UNIQUE,PRIMARY KEY(tenant_id,name)
);
CREATE TABLE public.sandy_supabase_service_events(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,actor_id uuid NOT NULL,
 admission_id uuid REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 operation text NOT NULL,before_sha256 text,after_sha256 text,
 occurred_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['sandy_supabase_tenant_consents','sandy_supabase_tenant_controls','sandy_supabase_managed_users','sandy_supabase_user_reservations','sandy_supabase_managed_channels','sandy_supabase_managed_buckets','sandy_supabase_managed_policies','sandy_supabase_managed_vault','sandy_supabase_service_events'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;
END $$;
CREATE FUNCTION public.sandy_supabase_service_events_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN RAISE EXCEPTION 'sandy_supabase_service_events_append_only' USING ERRCODE='23514'; END $$;
CREATE TRIGGER sandy_supabase_service_events_immutable BEFORE UPDATE OR DELETE ON public.sandy_supabase_service_events FOR EACH ROW EXECUTE FUNCTION public.sandy_supabase_service_events_immutable();

CREATE FUNCTION public.sandy_supabase_portal_tenant(p_user uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT CASE WHEN count(DISTINCT p.customer_id)=1 THEN (array_agg(DISTINCT p.customer_id))[1] ELSE NULL END
 FROM public.sandy_memory_portal_accounts p JOIN auth.users u ON u.id=p.auth_user_id AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL
 JOIN public.email_customer_addresses a ON a.customer_id=p.customer_id AND a.is_primary AND a.normalized_email=lower(u.email)
 WHERE p.auth_user_id=p_user AND p.revoked_at IS NULL
$$;
CREATE FUNCTION public.sandy_supabase_tenant_member(p_tenant uuid,p_user uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT coalesce(p_user IS NOT NULL AND (p_user=auth.uid() OR auth.role()='service_role') AND EXISTS(SELECT 1 FROM auth.users u WHERE u.id=p_user AND u.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL)
 AND (public.sandy_supabase_portal_tenant(p_user)=p_tenant OR EXISTS(SELECT 1 FROM public.sandy_supabase_managed_users b WHERE b.tenant_id=p_tenant AND b.user_id=p_user AND b.source='service_created')),false)
$$;
-- Restrictive companions apply only to the new namespace. Effective access
-- must match a service-owned per-subject command/prefix permission, even when
-- an existing application has a broader permissive policy on the same table.
CREATE FUNCTION public.sandy_supabase_resource_permission(p_kind text,p_resource text,p_user uuid,p_command text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant uuid;
BEGIN
 IF p_kind='storage' THEN
  SELECT b.tenant_id INTO tenant FROM public.sandy_supabase_managed_buckets b WHERE b.bucket_id=split_part(p_resource,'/',1);
  IF tenant IS NULL THEN RETURN true;END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sandy_supabase_managed_buckets b WHERE b.tenant_id=tenant AND b.state='active') THEN RETURN false;END IF;
 ELSIF p_kind='realtime' THEN
  SELECT c.tenant_id INTO tenant FROM public.sandy_supabase_managed_channels c WHERE p_resource='sandy-service-v1:'||c.tenant_id::text||':'||c.name;
  IF tenant IS NULL THEN RETURN true;END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sandy_supabase_managed_channels c WHERE c.tenant_id=tenant AND c.state='active' AND p_resource='sandy-service-v1:'||c.tenant_id::text||':'||c.name) THEN RETURN false;END IF;
 ELSE RETURN false;END IF;
 IF NOT public.sandy_supabase_tenant_member(tenant,p_user) THEN RETURN false;END IF;
 RETURN EXISTS(SELECT 1 FROM public.sandy_supabase_managed_policies p WHERE p.tenant_id=tenant AND p.kind=p_kind AND p.subject_user_id=p_user AND p.command=p_command
  AND CASE WHEN p_kind='storage' THEN left(p_resource,length(p.resource))=p.resource ELSE p_resource=p.resource END);
END $$;
CREATE POLICY sandy_service_storage_select_boundary ON storage.objects AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(public.sandy_supabase_resource_permission('storage',bucket_id||'/'||name,auth.uid(),'SELECT'));
CREATE POLICY sandy_service_storage_insert_boundary ON storage.objects AS RESTRICTIVE FOR INSERT TO anon,authenticated WITH CHECK(public.sandy_supabase_resource_permission('storage',bucket_id||'/'||name,auth.uid(),'INSERT'));
CREATE POLICY sandy_service_storage_update_boundary ON storage.objects AS RESTRICTIVE FOR UPDATE TO anon,authenticated USING(public.sandy_supabase_resource_permission('storage',bucket_id||'/'||name,auth.uid(),'UPDATE')) WITH CHECK(public.sandy_supabase_resource_permission('storage',bucket_id||'/'||name,auth.uid(),'UPDATE'));
CREATE POLICY sandy_service_storage_delete_boundary ON storage.objects AS RESTRICTIVE FOR DELETE TO anon,authenticated USING(public.sandy_supabase_resource_permission('storage',bucket_id||'/'||name,auth.uid(),'DELETE'));
CREATE FUNCTION public.sandy_supabase_realtime_permission(p_topic text,p_private boolean,p_user uuid,p_command text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM public.sandy_supabase_managed_channels c WHERE p_topic='sandy-service-v1:'||c.tenant_id::text||':'||c.name)
 THEN coalesce(p_private,false) AND public.sandy_supabase_resource_permission('realtime',p_topic,p_user,p_command) ELSE true END
$$;
CREATE POLICY sandy_service_realtime_select_boundary ON realtime.messages AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(public.sandy_supabase_realtime_permission(topic,private,auth.uid(),'SELECT'));
CREATE POLICY sandy_service_realtime_insert_boundary ON realtime.messages AS RESTRICTIVE FOR INSERT TO anon,authenticated WITH CHECK(public.sandy_supabase_realtime_permission(topic,private,auth.uid(),'INSERT'));
REVOKE ALL ON FUNCTION public.sandy_supabase_realtime_permission(text,boolean,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_supabase_realtime_permission(text,boolean,uuid,text) TO anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.sandy_supabase_resource_permission(text,text,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_supabase_resource_permission(text,text,uuid,text) TO anon,authenticated,service_role;
-- These two pure membership helpers are deliberately callable by RLS roles;
-- they reveal only whether the caller's known user is in a known tenant.
REVOKE ALL ON FUNCTION public.sandy_supabase_portal_tenant(uuid),public.sandy_supabase_tenant_member(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_supabase_tenant_member(uuid,uuid) TO anon,authenticated,service_role;

CREATE FUNCTION public.sandy_supabase_tenant_consent_get() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant uuid:=public.sandy_supabase_portal_tenant(auth.uid());c public.sandy_supabase_tenant_consents;controls public.sandy_supabase_tenant_controls;
BEGIN
 IF tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'error','confirmed_portal_customer_session_required','http_status',403);END IF;
 SELECT * INTO c FROM public.sandy_supabase_tenant_consents WHERE tenant_id=tenant;
 SELECT * INTO controls FROM public.sandy_supabase_tenant_controls WHERE tenant_id=tenant;
 RETURN jsonb_build_object('ok',true,'tenant_id',tenant,'operations',coalesce(c.operations,ARRAY[]::text[]),'approved_emails',coalesce(c.approved_emails,ARRAY[]::text[]),'allow_erasure',coalesce(c.allow_erasure,false),'expires_at',c.expires_at,'revision',coalesce(c.revision,0),'legal_hold',coalesce(controls.legal_hold,false),'retention_until',controls.retention_until);
END $$;
CREATE FUNCTION public.sandy_supabase_tenant_consent_set(p_operations text[],p_approved_emails text[],p_allow_erasure boolean,p_expires_at timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant uuid:=public.sandy_supabase_portal_tenant(auth.uid());old_policy jsonb;new_policy jsonb;op text;email text;
BEGIN
 IF tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'error','confirmed_portal_customer_session_required','http_status',403);END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation='supabase.tenant.consent.set' AND handler='sandy-operation-api' AND api_exposed AND verified AND error_contract->>'requires_real_user_session'='true') THEN RETURN jsonb_build_object('ok',false,'error','verified_tenant_consent_contract_required','http_status',424);END IF;
 IF p_operations IS NULL OR cardinality(p_operations)>64 OR array_position(p_operations,NULL) IS NOT NULL
 OR (SELECT count(DISTINCT x) FROM unnest(p_operations) x)<>cardinality(p_operations)
 OR p_approved_emails IS NULL OR cardinality(p_approved_emails)>8 OR array_position(p_approved_emails,NULL) IS NOT NULL
 OR p_allow_erasure IS NULL OR p_expires_at IS NULL OR p_expires_at<=clock_timestamp() OR p_expires_at>clock_timestamp()+interval '30 days' THEN RAISE EXCEPTION 'tenant_consent_invalid';END IF;
 FOREACH op IN ARRAY p_operations LOOP
  IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation=op AND handler='sandy-supabase-service-api') THEN RAISE EXCEPTION 'tenant_consent_operation_invalid';END IF;
 END LOOP;
 FOREACH email IN ARRAY p_approved_emails LOOP
  IF email IS DISTINCT FROM lower(email) OR octet_length(email)>254 OR email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'tenant_consent_email_invalid';END IF;
 END LOOP;
 PERFORM pg_advisory_xact_lock(hashtextextended('sandy_tenant_policy:'||tenant::text,0));
 SELECT to_jsonb(c) INTO old_policy FROM public.sandy_supabase_tenant_consents c WHERE tenant_id=tenant FOR UPDATE;
 INSERT INTO public.sandy_supabase_tenant_consents(tenant_id,auth_user_id,operations,approved_emails,allow_erasure,expires_at)
 VALUES(tenant,auth.uid(),p_operations,p_approved_emails,p_allow_erasure,p_expires_at)
 ON CONFLICT(tenant_id) DO UPDATE SET auth_user_id=excluded.auth_user_id,operations=excluded.operations,approved_emails=excluded.approved_emails,allow_erasure=excluded.allow_erasure,expires_at=excluded.expires_at,revision=sandy_supabase_tenant_consents.revision+1,updated_at=clock_timestamp();
 INSERT INTO public.sandy_supabase_managed_users(tenant_id,user_id,source) VALUES(tenant,auth.uid(),'confirmed_portal_self') ON CONFLICT DO NOTHING;
 INSERT INTO public.sandy_supabase_tenant_controls(tenant_id) VALUES(tenant) ON CONFLICT DO NOTHING;
 SELECT to_jsonb(c) INTO new_policy FROM public.sandy_supabase_tenant_consents c WHERE tenant_id=tenant;
 INSERT INTO public.sandy_supabase_service_events(tenant_id,actor_id,operation,before_sha256,after_sha256) VALUES(tenant,auth.uid(),'supabase.tenant.consent.set',CASE WHEN old_policy IS NULL THEN NULL ELSE encode(extensions.digest(old_policy::text,'sha256'),'hex') END,encode(extensions.digest(new_policy::text,'sha256'),'hex'));
 RETURN public.sandy_supabase_tenant_consent_get();
END $$;
REVOKE ALL ON FUNCTION public.sandy_supabase_tenant_consent_get(),public.sandy_supabase_tenant_consent_set(text[],text[],boolean,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_supabase_tenant_consent_get(),public.sandy_supabase_tenant_consent_set(text[],text[],boolean,timestamptz) TO authenticated;

CREATE FUNCTION public.sandy_supabase_service_context(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE a public.sandy_api_execution_admissions;r public.sandy_operation_registry;args jsonb;c public.sandy_supabase_tenant_consents;controls public.sandy_supabase_tenant_controls;tenant uuid;target uuid;v_email text;
BEGIN
 IF p_actor IS NULL OR p_admission IS NULL OR p_canonical IS NULL OR octet_length(p_canonical)>196608 THEN RAISE EXCEPTION 'service_context_invalid';END IF;
 args:=p_canonical::jsonb;tenant:=(args->>'tenant_id')::uuid;
 SELECT * INTO a FROM public.sandy_api_execution_admissions WHERE id=p_admission FOR SHARE;
 IF a.id IS NULL OR a.actor_id IS DISTINCT FROM p_actor OR a.tenant_id IS NOT NULL OR a.credential_id IS NOT NULL OR a.state IS DISTINCT FROM 'consumed' OR a.expires_at<=clock_timestamp()
 OR a.scope_sha256 IS DISTINCT FROM '04573c462b9fa724cc78afc55ca40999b05855765084fc1c1e449fd8e06f2a14' OR a.input_sha256 IS DISTINCT FROM encode(extensions.digest(p_canonical,'sha256'),'hex') OR NOT public.sandy_api_current_owner(p_actor) THEN RAISE EXCEPTION 'service_scoped_admission_required';END IF;
 SELECT * INTO r FROM public.sandy_operation_registry WHERE operation=a.operation FOR SHARE;
 IF r.operation IS NULL OR r.handler IS DISTINCT FROM 'sandy-supabase-service-api' OR r.api_exposed IS DISTINCT FROM true OR r.verified IS DISTINCT FROM true
 OR r.error_contract->>'contract_sha256' IS DISTINCT FROM a.contract_sha256 OR public.sandy_api_registry_revision(a.operation) IS DISTINCT FROM a.registry_revision_sha256 THEN RAISE EXCEPTION 'service_current_verified_contract_required';END IF;
 IF tenant IS NULL OR NOT EXISTS(SELECT 1 FROM public.email_customers WHERE id=tenant) THEN RAISE EXCEPTION 'service_tenant_required';END IF;
 SELECT * INTO controls FROM public.sandy_supabase_tenant_controls WHERE tenant_id=tenant FOR SHARE;
 SELECT * INTO c FROM public.sandy_supabase_tenant_consents WHERE tenant_id=tenant FOR SHARE;
 IF a.operation NOT IN('supabase.compliance.audit','supabase.compliance.hold.create','supabase.compliance.retention.extend') AND (c.tenant_id IS NULL OR c.expires_at<=clock_timestamp() OR public.sandy_supabase_portal_tenant(c.auth_user_id) IS DISTINCT FROM tenant OR NOT a.operation=ANY(c.operations)) THEN RAISE EXCEPTION 'current_explicit_tenant_consent_required';END IF;
 IF a.operation IN('supabase.auth.users.delete','supabase.storage.buckets.empty','supabase.storage.buckets.delete','supabase.storage.objects.delete','supabase.storage.objects.update','supabase.storage.objects.move','supabase.vault.secrets.managed.delete','supabase.vault.secrets.managed.update')
 AND (c.allow_erasure IS DISTINCT FROM true OR controls.legal_hold IS TRUE OR controls.retention_until>clock_timestamp()) THEN RAISE EXCEPTION 'tenant_erasure_retention_or_legal_hold_refused';END IF;
 IF a.operation LIKE 'supabase.storage.%' THEN
  IF a.operation='supabase.storage.buckets.create' THEN
   IF EXISTS(SELECT 1 FROM storage.buckets WHERE id='sandy-service-v1-tenant-'||tenant::text)
   OR EXISTS(SELECT 1 FROM public.sandy_supabase_managed_buckets b WHERE b.tenant_id=tenant AND b.state<>'deleted') THEN RAISE EXCEPTION 'existing_or_reserved_bucket_adoption_refused';END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.sandy_supabase_managed_buckets b JOIN storage.buckets provider ON provider.id=b.bucket_id WHERE b.tenant_id=tenant AND b.bucket_id='sandy-service-v1-tenant-'||tenant::text AND b.state='active') AND NOT (a.operation='supabase.storage.buckets.delete' AND EXISTS(SELECT 1 FROM public.sandy_supabase_managed_buckets b WHERE b.tenant_id=tenant AND b.state='active')) THEN RAISE EXCEPTION 'active_service_owned_bucket_required';END IF;
 END IF;
 IF args ? 'user_id' THEN
  target:=(args->>'user_id')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.sandy_supabase_managed_users WHERE tenant_id=tenant AND user_id=target) THEN RAISE EXCEPTION 'tenant_managed_user_required';END IF;
  IF r.is_mutation AND (EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=target) OR EXISTS(SELECT 1 FROM auth.users WHERE id=target AND (raw_app_meta_data->>'sandy_gcp_machine'='true' OR is_super_admin IS TRUE))) THEN RAISE EXCEPTION 'protected_system_identity_refused';END IF;
 END IF;
 IF args ? 'subject_user_id' AND NOT public.sandy_supabase_tenant_member(tenant,(args->>'subject_user_id')::uuid) THEN RAISE EXCEPTION 'tenant_policy_subject_required';END IF;
 IF a.operation='supabase.realtime.channels.subscribe' AND NOT EXISTS(SELECT 1 FROM public.sandy_supabase_managed_channels ch WHERE ch.tenant_id=tenant AND ch.state='active' AND ch.name=args->>'name') THEN RAISE EXCEPTION 'managed_channel_required';END IF;
 IF a.operation='supabase.auth.users.create' THEN
  v_email:=lower(args->>'email');
  IF v_email IS NULL OR v_email IS DISTINCT FROM args->>'email' OR NOT v_email=ANY(c.approved_emails) OR EXISTS(SELECT 1 FROM auth.users u WHERE lower(u.email)=v_email) THEN RAISE EXCEPTION 'explicit_new_managed_email_required';END IF;
 END IF;
 IF args ? 'path' AND (args->>'path' !~ '^[A-Za-z0-9_./ -]+$' OR args->>'path' ~ '(^/|(^|/)\.{1,2}(/|$))' OR octet_length(args->>'path')>1024) THEN RAISE EXCEPTION 'storage_path_invalid';END IF;
 IF args ? 'destination' AND (args->>'destination' !~ '^[A-Za-z0-9_./ -]+$' OR args->>'destination' ~ '(^/|(^|/)\.{1,2}(/|$))' OR octet_length(args->>'destination')>1024) THEN RAISE EXCEPTION 'storage_destination_invalid';END IF;
 RETURN jsonb_build_object('tenant_id',tenant,'operation',a.operation,'arguments',args,'consent_revision',coalesce(c.revision,0),'bucket_id','sandy-service-v1-tenant-'||tenant::text);
END $$;
CREATE FUNCTION public.sandy_supabase_service_authorize(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE ctx jsonb;args jsonb;tenant uuid;
BEGIN
 ctx:=public.sandy_supabase_service_context(p_actor,p_admission,p_canonical);args:=ctx->'arguments';tenant:=(ctx->>'tenant_id')::uuid;
 IF ctx->>'operation'='supabase.storage.buckets.create' THEN INSERT INTO public.sandy_supabase_managed_buckets(tenant_id,bucket_id,creation_admission_id,state) VALUES(tenant,ctx->>'bucket_id',p_admission,'reserved') ON CONFLICT(tenant_id) DO UPDATE SET creation_admission_id=excluded.creation_admission_id,state='reserved',bound_at=NULL WHERE sandy_supabase_managed_buckets.state='deleted';END IF;
 IF ctx->>'operation'='supabase.auth.users.create' THEN INSERT INTO public.sandy_supabase_user_reservations(admission_id,tenant_id,normalized_email) VALUES(p_admission,tenant,args->>'email');END IF;
 RETURN jsonb_build_object('ok',true,'bucket_id',ctx->>'bucket_id','consent_revision',ctx->'consent_revision','user_ids',(SELECT coalesce(jsonb_agg(user_id ORDER BY user_id),'[]'::jsonb) FROM public.sandy_supabase_managed_users WHERE tenant_id=tenant));
END $$;
CREATE FUNCTION public.sandy_supabase_service_bind_user(p_actor uuid,p_admission uuid,p_user uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE a public.sandy_api_execution_admissions;reservation public.sandy_supabase_user_reservations;u auth.users;
BEGIN
 SELECT * INTO a FROM public.sandy_api_execution_admissions WHERE id=p_admission FOR SHARE;
 SELECT * INTO reservation FROM public.sandy_supabase_user_reservations WHERE admission_id=p_admission FOR UPDATE;
 SELECT * INTO u FROM auth.users WHERE id=p_user FOR SHARE;
 IF a.id IS NULL OR a.actor_id IS DISTINCT FROM p_actor OR a.operation IS DISTINCT FROM 'supabase.auth.users.create' OR a.state IS DISTINCT FROM 'consumed' OR a.expires_at<=clock_timestamp() OR a.credential_id IS NOT NULL
 OR NOT public.sandy_api_current_owner(p_actor) OR reservation.admission_id IS NULL OR lower(u.email) IS DISTINCT FROM reservation.normalized_email OR u.raw_user_meta_data->>'sandy_creation_admission' IS DISTINCT FROM p_admission::text OR u.raw_app_meta_data->>'sandy_gcp_machine'='true'
 OR EXISTS(SELECT 1 FROM public.sandy_controller_admins WHERE auth_user_id=p_user) THEN RAISE EXCEPTION 'service_created_user_binding_refused';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry r WHERE r.operation=a.operation AND r.api_exposed AND r.verified AND r.handler='sandy-supabase-service-api' AND r.error_contract->>'contract_sha256'=a.contract_sha256 AND public.sandy_api_registry_revision(a.operation)=a.registry_revision_sha256) THEN RAISE EXCEPTION 'service_current_verified_contract_required';END IF;
 IF reservation.user_id IS NOT NULL AND reservation.user_id<>p_user THEN RAISE EXCEPTION 'service_created_user_binding_conflict';END IF;
 INSERT INTO public.sandy_supabase_managed_users(tenant_id,user_id,source,creation_admission_id) VALUES(reservation.tenant_id,p_user,'service_created',p_admission) ON CONFLICT DO NOTHING;
 UPDATE public.sandy_supabase_user_reservations SET user_id=p_user WHERE admission_id=p_admission;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.sandy_supabase_service_bind_bucket(p_actor uuid,p_admission uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE a public.sandy_api_execution_admissions;b public.sandy_supabase_managed_buckets;provider storage.buckets;
BEGIN
 SELECT * INTO a FROM public.sandy_api_execution_admissions WHERE id=p_admission FOR SHARE;
 SELECT * INTO b FROM public.sandy_supabase_managed_buckets WHERE creation_admission_id=p_admission FOR UPDATE;
 SELECT * INTO provider FROM storage.buckets WHERE id=b.bucket_id FOR SHARE;
 IF a.id IS NULL OR a.actor_id IS DISTINCT FROM p_actor OR a.operation IS DISTINCT FROM 'supabase.storage.buckets.create' OR a.state IS DISTINCT FROM 'consumed' OR a.expires_at<=clock_timestamp() OR NOT public.sandy_api_current_owner(p_actor)
 OR b.tenant_id IS NULL OR b.state IS DISTINCT FROM 'reserved' OR provider.id IS NULL OR provider.public IS DISTINCT FROM false OR provider.created_at<a.created_at THEN RAISE EXCEPTION 'created_bucket_binding_refused';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry r WHERE r.operation=a.operation AND r.handler='sandy-supabase-service-api' AND r.api_exposed AND r.verified AND r.error_contract->>'contract_sha256'=a.contract_sha256 AND public.sandy_api_registry_revision(a.operation)=a.registry_revision_sha256) THEN RAISE EXCEPTION 'service_current_verified_contract_required';END IF;
 UPDATE public.sandy_supabase_managed_buckets SET state='active',bound_at=clock_timestamp() WHERE tenant_id=b.tenant_id;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE FUNCTION public.sandy_supabase_service_release_bucket(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE ctx jsonb;tenant uuid;
BEGIN
 ctx:=public.sandy_supabase_service_context(p_actor,p_admission,p_canonical);tenant:=(ctx->>'tenant_id')::uuid;
 IF ctx->>'operation' IS DISTINCT FROM 'supabase.storage.buckets.delete' OR EXISTS(SELECT 1 FROM storage.buckets WHERE id=ctx->>'bucket_id') THEN RAISE EXCEPTION 'deleted_bucket_readback_required';END IF;
 UPDATE public.sandy_supabase_managed_buckets SET state='deleted' WHERE tenant_id=tenant AND state='active';
 IF NOT FOUND THEN RAISE EXCEPTION 'active_bucket_binding_required';END IF;
 RETURN jsonb_build_object('ok',true);
END $$;
CREATE TABLE public.sandy_supabase_service_results(
 admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 result jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.sandy_supabase_service_results ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_supabase_service_results FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.sandy_supabase_service_execute(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE ctx jsonb;args jsonb;tenant uuid;op text;result jsonb;before_value jsonb;after_value jsonb;resource text;before_hash text;after_hash text;v_kind text;action text;provider_name text;expr text;command text;definition text;existing_definition text;subject uuid;secret_name text;secret_id uuid;stored_value text;v_offset integer;v_limit integer;v_count integer;previous_result jsonb;binding public.sandy_supabase_managed_policies;channel public.sandy_supabase_managed_channels;
BEGIN
 -- Serialize receipts before any SQL side effect. A retry can observe the
 -- same immutable result, but cannot repeat the mutation.
 PERFORM id FROM public.sandy_api_execution_admissions WHERE id=p_admission FOR UPDATE;
 ctx:=public.sandy_supabase_service_context(p_actor,p_admission,p_canonical);args:=ctx->'arguments';tenant:=(ctx->>'tenant_id')::uuid;op:=ctx->>'operation';
 SELECT r.result INTO previous_result FROM public.sandy_supabase_service_results r WHERE r.admission_id=p_admission;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'result',previous_result,'reused',true);END IF;
 IF op='supabase.auth.sessions.list' THEN
  v_offset:=coalesce((args->>'offset')::integer,0);v_limit:=coalesce((args->>'limit')::integer,100);
  IF v_offset NOT BETWEEN 0 AND 10000 OR v_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'session_pagination_invalid';END IF;
  SELECT count(*) INTO v_count FROM auth.sessions WHERE user_id=(args->>'user_id')::uuid;
  SELECT jsonb_build_object('sessions',coalesce(jsonb_agg(row),'[]'::jsonb),'next_offset',CASE WHEN v_count>v_offset+v_limit THEN v_offset+v_limit ELSE NULL END) INTO result
   FROM(SELECT id,user_id,created_at,updated_at,aal,not_after,refreshed_at FROM auth.sessions WHERE user_id=(args->>'user_id')::uuid ORDER BY created_at,id LIMIT v_limit OFFSET v_offset) row;
 ELSIF op LIKE 'supabase.storage.policies.%' OR op LIKE 'supabase.realtime.permissions.%' THEN
  v_kind:=CASE WHEN op LIKE 'supabase.storage.%' THEN 'storage' ELSE 'realtime' END;action:=split_part(op,'.',4);
  IF action='list' THEN
   SELECT jsonb_build_object('policies',coalesce(jsonb_agg(jsonb_build_object('name',p.name,'command',p.command,'subject_user_id',p.subject_user_id,'resource',p.resource) ORDER BY p.name),'[]'::jsonb)) INTO result FROM public.sandy_supabase_managed_policies p WHERE p.tenant_id=tenant AND p.kind=v_kind;
  ELSE
   IF args->>'name' !~ '^[a-z][a-z0-9_]{0,35}$' THEN RAISE EXCEPTION 'managed_policy_name_invalid';END IF;
   subject:=(args->>'subject_user_id')::uuid;
   SELECT p.* INTO binding FROM public.sandy_supabase_managed_policies p WHERE p.tenant_id=tenant AND p.kind=v_kind AND p.name=args->>'name' FOR UPDATE;
   provider_name:='ss_'||substr(encode(extensions.digest(tenant::text||':'||v_kind||':'||(args->>'name'),'sha256'),'hex'),1,40);
   IF action='create' AND binding.provider_name IS NOT NULL THEN RAISE EXCEPTION 'managed_policy_already_exists';END IF;
   IF action IN('update','delete') AND binding.provider_name IS NULL THEN RAISE EXCEPTION 'managed_policy_not_found';END IF;
   IF action='create' AND (SELECT count(*) FROM public.sandy_supabase_managed_policies p WHERE p.tenant_id=tenant AND p.kind=v_kind)>=100 THEN RAISE EXCEPTION 'managed_policy_limit_reached';END IF;
   IF binding.provider_name IS NOT NULL THEN
    SELECT coalesce(pg_get_expr(p.polqual,p.polrelid),'')||'|'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') INTO existing_definition FROM pg_policy p WHERE p.polname=binding.provider_name AND p.polrelid=CASE WHEN v_kind='storage' THEN 'storage.objects'::regclass ELSE 'realtime.messages'::regclass END;
    IF existing_definition IS NULL OR encode(extensions.digest(existing_definition,'sha256'),'hex') IS DISTINCT FROM binding.definition_sha256 THEN RAISE EXCEPTION 'managed_policy_provider_drift_refused';END IF;
    before_value:=jsonb_build_object('name',binding.name,'command',binding.command,'subject_user_id',binding.subject_user_id,'resource',binding.resource,'definition_sha256',binding.definition_sha256);
    IF action='delete' AND subject IS DISTINCT FROM binding.subject_user_id THEN RAISE EXCEPTION 'managed_policy_subject_mismatch';END IF;
    EXECUTE format('DROP POLICY %I ON %s',binding.provider_name,CASE WHEN v_kind='storage' THEN 'storage.objects' ELSE 'realtime.messages' END);
    DELETE FROM public.sandy_supabase_managed_policies p WHERE p.tenant_id=tenant AND p.kind=v_kind AND p.name=args->>'name';
   END IF;
   IF action<>'delete' THEN
    command:=args->>'command';
    IF v_kind='storage' THEN
     IF command NOT IN('SELECT','INSERT','UPDATE','DELETE') OR coalesce(args->>'prefix','') !~ '^[A-Za-z0-9_./ -]*$' OR coalesce(args->>'prefix','') ~ '(^/|(^|/)\.{1,2}(/|$))' OR octet_length(coalesce(args->>'prefix',''))>500 THEN RAISE EXCEPTION 'storage_policy_arguments_invalid';END IF;
     resource:=(ctx->>'bucket_id')||'/'||coalesce(args->>'prefix','');
     expr:=format('bucket_id=%L AND left(name,%s)=%L AND auth.uid()=%L::uuid AND public.sandy_supabase_tenant_member(%L::uuid,auth.uid())',ctx->>'bucket_id',length(coalesce(args->>'prefix','')),coalesce(args->>'prefix',''),subject::text,tenant::text);
    ELSE
     IF command NOT IN('SELECT','INSERT') OR args->>'channel' !~ '^[a-z][a-z0-9_-]{0,63}$' OR NOT EXISTS(SELECT 1 FROM public.sandy_supabase_managed_channels c WHERE c.tenant_id=tenant AND c.state='active' AND c.name=args->>'channel') THEN RAISE EXCEPTION 'realtime_policy_arguments_invalid';END IF;
     resource:='sandy-service-v1:'||tenant::text||':'||(args->>'channel');
     expr:=format('topic=%L AND private AND extension IN (''broadcast'',''presence'') AND auth.uid()=%L::uuid AND public.sandy_supabase_tenant_member(%L::uuid,auth.uid())',resource,subject::text,tenant::text);
    END IF;
    definition:=format('CREATE POLICY %I ON %s FOR %s TO authenticated',provider_name,CASE WHEN v_kind='storage' THEN 'storage.objects' ELSE 'realtime.messages' END,command);
    IF command IN('SELECT','UPDATE','DELETE') THEN definition:=definition||' USING ('||expr||')';END IF;
    IF command IN('INSERT','UPDATE') THEN definition:=definition||' WITH CHECK ('||expr||')';END IF;
    EXECUTE definition;
    SELECT coalesce(pg_get_expr(p.polqual,p.polrelid),'')||'|'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') INTO existing_definition FROM pg_policy p WHERE p.polname=provider_name AND p.polrelid=CASE WHEN v_kind='storage' THEN 'storage.objects'::regclass ELSE 'realtime.messages'::regclass END;
    IF existing_definition IS NULL THEN RAISE EXCEPTION 'managed_policy_readback_failed';END IF;
    after_hash:=encode(extensions.digest(existing_definition,'sha256'),'hex');
    INSERT INTO public.sandy_supabase_managed_policies(tenant_id,kind,name,provider_name,subject_user_id,command,resource,definition_sha256) VALUES(tenant,v_kind,args->>'name',provider_name,subject,command,resource,after_hash);
    after_value:=jsonb_build_object('name',args->>'name','command',command,'subject_user_id',subject,'resource',resource,'definition_sha256',after_hash);
   END IF;
   result:=jsonb_build_object('resource_id',provider_name,'before_sha256',CASE WHEN before_value IS NULL THEN NULL ELSE encode(extensions.digest(before_value::text,'sha256'),'hex') END,'after_sha256',CASE WHEN after_value IS NULL THEN NULL ELSE encode(extensions.digest(after_value::text,'sha256'),'hex') END,'readback_verified',true);
  END IF;
 ELSIF op LIKE 'supabase.realtime.channels.%' THEN
  action:=split_part(op,'.',4);
  IF action='list' THEN
   SELECT jsonb_build_object('channels',coalesce(jsonb_agg(jsonb_build_object('name',c.name,'topic','sandy-service-v1:'||tenant::text||':'||c.name,'description',c.description,'revision',c.revision) ORDER BY c.name),'[]'::jsonb)) INTO result FROM public.sandy_supabase_managed_channels c WHERE c.tenant_id=tenant AND c.state='active';
  ELSE
   IF args->>'name' !~ '^[a-z][a-z0-9_-]{0,63}$' THEN RAISE EXCEPTION 'managed_channel_name_invalid';END IF;
   SELECT c.* INTO channel FROM public.sandy_supabase_managed_channels c WHERE c.tenant_id=tenant AND c.name=args->>'name' FOR UPDATE;
   before_value:=CASE WHEN channel.name IS NULL OR channel.state<>'active' THEN NULL ELSE jsonb_build_object('name',channel.name,'topic','sandy-service-v1:'||tenant::text||':'||channel.name,'description',channel.description,'revision',channel.revision) END;
   IF action='get' THEN
    IF before_value IS NULL THEN RAISE EXCEPTION 'managed_channel_not_found';END IF;
    result:=jsonb_build_object('channel',before_value);
   ELSE
    IF action='create' THEN
     IF (channel.name IS NOT NULL AND channel.state='active') OR (SELECT count(*) FROM public.sandy_supabase_managed_channels c WHERE c.tenant_id=tenant AND c.state='active')>=100 THEN RAISE EXCEPTION 'managed_channel_already_exists_or_limit';END IF;
     INSERT INTO public.sandy_supabase_managed_channels(tenant_id,name,description) VALUES(tenant,args->>'name',coalesce(args->>'description','')) ON CONFLICT(tenant_id,name) DO UPDATE SET description=excluded.description,state='active',revision=sandy_supabase_managed_channels.revision+1;
    ELSIF action='update' THEN
     IF channel.name IS NULL OR channel.state<>'active' THEN RAISE EXCEPTION 'managed_channel_not_found';END IF;
     UPDATE public.sandy_supabase_managed_channels c SET description=coalesce(args->>'description',''),revision=c.revision+1 WHERE c.tenant_id=tenant AND c.name=args->>'name';
    ELSIF action='delete' THEN
     IF channel.name IS NULL OR channel.state<>'active' OR EXISTS(SELECT 1 FROM public.sandy_supabase_managed_policies p WHERE p.tenant_id=tenant AND p.kind='realtime' AND p.resource='sandy-service-v1:'||tenant::text||':'||(args->>'name')) THEN RAISE EXCEPTION 'managed_channel_missing_or_policies_present';END IF;
     UPDATE public.sandy_supabase_managed_channels c SET state='deleted',revision=c.revision+1 WHERE c.tenant_id=tenant AND c.name=args->>'name';
    ELSE RAISE EXCEPTION 'managed_channel_operation_unsupported';END IF;
    SELECT jsonb_build_object('name',c.name,'topic','sandy-service-v1:'||tenant::text||':'||c.name,'description',c.description,'revision',c.revision) INTO after_value FROM public.sandy_supabase_managed_channels c WHERE c.tenant_id=tenant AND c.state='active' AND c.name=args->>'name';
    result:=jsonb_build_object('resource_id','sandy-service-v1:'||tenant::text||':'||(args->>'name'),'before_sha256',CASE WHEN before_value IS NULL THEN NULL ELSE encode(extensions.digest(before_value::text,'sha256'),'hex') END,'after_sha256',CASE WHEN after_value IS NULL THEN NULL ELSE encode(extensions.digest(after_value::text,'sha256'),'hex') END,'readback_verified',true);
   END IF;
  END IF;
 ELSIF op LIKE 'supabase.vault.secrets.managed.%' THEN
  action:=split_part(op,'.',5);
  IF action='list' THEN
   SELECT jsonb_build_object('secrets',coalesce(jsonb_agg(jsonb_build_object('id',v.id,'name',b.name,'description',v.description,'created_at',v.created_at,'updated_at',v.updated_at) ORDER BY b.name),'[]'::jsonb)) INTO result FROM public.sandy_supabase_managed_vault b JOIN vault.secrets v ON v.id=b.secret_id WHERE b.tenant_id=tenant;
  ELSE
   IF args->>'name' !~ '^[a-z][a-z0-9_]{0,63}$' THEN RAISE EXCEPTION 'managed_vault_name_invalid';END IF;
   secret_name:='sandy_service_'||replace(tenant::text,'-','')||'_'||(args->>'name');
   SELECT b.secret_id INTO secret_id FROM public.sandy_supabase_managed_vault b WHERE b.tenant_id=tenant AND b.name=args->>'name' FOR UPDATE;
   SELECT jsonb_build_object('id',v.id,'name',args->>'name','description',v.description,'created_at',v.created_at,'updated_at',v.updated_at) INTO before_value FROM vault.secrets v WHERE v.id=secret_id AND v.name=secret_name;
   IF action IN('update','delete') AND EXISTS(SELECT 1 FROM public.sandy_credential_versions cv WHERE cv.vault_secret_id=secret_id) THEN RAISE EXCEPTION 'credential_custody_material_protected';END IF;
   IF action='get' THEN
    IF before_value IS NULL THEN RAISE EXCEPTION 'managed_vault_secret_not_found_or_drift';END IF;
    result:=jsonb_build_object('secret',before_value);
   ELSE
    IF action IN('create','update') AND (args->>'value' IS NULL OR octet_length(args->>'value') NOT BETWEEN 1 AND 65536 OR octet_length(coalesce(args->>'description',''))>300) THEN RAISE EXCEPTION 'managed_vault_value_invalid';END IF;
    IF action='create' THEN
     IF secret_id IS NOT NULL OR EXISTS(SELECT 1 FROM vault.secrets WHERE name=secret_name) OR (SELECT count(*) FROM public.sandy_supabase_managed_vault b WHERE b.tenant_id=tenant)>=100 THEN RAISE EXCEPTION 'managed_vault_secret_already_exists_or_limit';END IF;
     SELECT vault.create_secret(args->>'value',secret_name,coalesce(args->>'description','')) INTO secret_id;
     INSERT INTO public.sandy_supabase_managed_vault(tenant_id,name,secret_id) VALUES(tenant,args->>'name',secret_id);
    ELSIF action='update' THEN
     IF before_value IS NULL THEN RAISE EXCEPTION 'managed_vault_secret_not_found_or_drift';END IF;
     PERFORM vault.update_secret(secret_id,args->>'value',secret_name,coalesce(args->>'description',''));
    ELSIF action='delete' THEN
     IF before_value IS NULL THEN RAISE EXCEPTION 'managed_vault_secret_not_found_or_drift';END IF;
     DELETE FROM vault.secrets WHERE id=secret_id AND name=secret_name;
     DELETE FROM public.sandy_supabase_managed_vault b WHERE b.tenant_id=tenant AND b.name=args->>'name';
    ELSE RAISE EXCEPTION 'managed_vault_operation_unsupported';END IF;
    IF action<>'delete' THEN
     SELECT decrypted_secret INTO stored_value FROM vault.decrypted_secrets WHERE id=secret_id;
     IF stored_value IS DISTINCT FROM args->>'value' THEN RAISE EXCEPTION 'managed_vault_readback_failed';END IF;
     SELECT jsonb_build_object('id',v.id,'name',args->>'name','description',v.description,'created_at',v.created_at,'updated_at',v.updated_at) INTO after_value FROM vault.secrets v WHERE v.id=secret_id AND v.name=secret_name;
    END IF;
    result:=jsonb_build_object('resource_id',secret_id,'before_sha256',CASE WHEN before_value IS NULL THEN NULL ELSE encode(extensions.digest(before_value::text,'sha256'),'hex') END,'after_sha256',CASE WHEN after_value IS NULL THEN NULL ELSE encode(extensions.digest(after_value::text,'sha256'),'hex') END,'readback_verified',true);
   END IF;
  END IF;
 ELSIF op IN('supabase.compliance.hold.create','supabase.compliance.retention.extend') THEN
  SELECT to_jsonb(c) INTO before_value FROM public.sandy_supabase_tenant_controls c WHERE c.tenant_id=tenant FOR UPDATE;
  INSERT INTO public.sandy_supabase_tenant_controls(tenant_id) VALUES(tenant) ON CONFLICT DO NOTHING;
  IF op='supabase.compliance.hold.create' THEN
   IF octet_length(coalesce(args->>'reason','')) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'legal_hold_reason_required';END IF;
   UPDATE public.sandy_supabase_tenant_controls c SET legal_hold=true,updated_at=clock_timestamp() WHERE c.tenant_id=tenant;
  ELSE
   IF (args->>'retain_until')::timestamptz<=clock_timestamp() OR (args->>'retain_until')::timestamptz>clock_timestamp()+interval '10 years' OR EXISTS(SELECT 1 FROM public.sandy_supabase_tenant_controls c WHERE c.tenant_id=tenant AND c.retention_until>(args->>'retain_until')::timestamptz) THEN RAISE EXCEPTION 'retention_may_only_extend';END IF;
   UPDATE public.sandy_supabase_tenant_controls c SET retention_until=(args->>'retain_until')::timestamptz,updated_at=clock_timestamp() WHERE c.tenant_id=tenant;
  END IF;
  SELECT to_jsonb(c) INTO after_value FROM public.sandy_supabase_tenant_controls c WHERE c.tenant_id=tenant;
  result:=jsonb_build_object('resource_id',tenant,'before_sha256',CASE WHEN before_value IS NULL THEN NULL ELSE encode(extensions.digest(before_value::text,'sha256'),'hex') END,'after_sha256',encode(extensions.digest(after_value::text,'sha256'),'hex'),'readback_verified',true);
 ELSIF op='supabase.compliance.audit' THEN
  SELECT jsonb_build_object('tenant_id',tenant,'policy_present',c.tenant_id IS NOT NULL,'consent_current',coalesce(c.expires_at>clock_timestamp() AND public.sandy_supabase_portal_tenant(c.auth_user_id)=tenant,false),'legal_hold',coalesce(controls.legal_hold,false),'retention_until',controls.retention_until,'consent_version',coalesce(c.revision,0),
   'managed_users',(SELECT count(*) FROM public.sandy_supabase_managed_users b WHERE b.tenant_id=tenant),'managed_channels',(SELECT count(*) FROM public.sandy_supabase_managed_channels b WHERE b.tenant_id=tenant),'managed_policies',(SELECT count(*) FROM public.sandy_supabase_managed_policies b WHERE b.tenant_id=tenant),'managed_vault_secrets',(SELECT count(*) FROM public.sandy_supabase_managed_vault b WHERE b.tenant_id=tenant),'consent_audit_events',(SELECT count(*) FROM public.sandy_supabase_service_events b WHERE b.tenant_id=tenant),
   'coverage','managed_resources_only','complete_tenant_manifest_verified',false,'external_audit_anchor_verified',false) INTO result
   FROM(SELECT tenant AS tenant_id) t LEFT JOIN public.sandy_supabase_tenant_consents c USING(tenant_id) LEFT JOIN public.sandy_supabase_tenant_controls controls USING(tenant_id);
 ELSE RAISE EXCEPTION 'service_sql_operation_not_implemented';END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'service_result_required';END IF;
 INSERT INTO public.sandy_supabase_service_results(admission_id,result) VALUES(p_admission,result);
 IF (SELECT is_mutation FROM public.sandy_operation_registry WHERE operation=op) THEN
  INSERT INTO public.sandy_supabase_service_events(tenant_id,actor_id,admission_id,operation,before_sha256,after_sha256) VALUES(tenant,p_actor,p_admission,op,result->>'before_sha256',result->>'after_sha256');
 END IF;
 RETURN jsonb_build_object('ok',true,'result',result,'reused',false);
END $$;
REVOKE ALL ON FUNCTION public.sandy_supabase_service_events_immutable(),public.sandy_supabase_service_context(uuid,uuid,text),public.sandy_supabase_service_authorize(uuid,uuid,text),public.sandy_supabase_service_bind_user(uuid,uuid,uuid),public.sandy_supabase_service_execute(uuid,uuid,text),public.sandy_supabase_service_bind_bucket(uuid,uuid),public.sandy_supabase_service_release_bucket(uuid,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_supabase_service_authorize(uuid,uuid,text),public.sandy_supabase_service_bind_user(uuid,uuid,uuid),public.sandy_supabase_service_execute(uuid,uuid,text),public.sandy_supabase_service_bind_bucket(uuid,uuid),public.sandy_supabase_service_release_bucket(uuid,uuid,text) TO service_role;

DO $contracts$
DECLARE contract jsonb;
BEGIN
 contract := $contract${"operation":"supabase.auth.users.list","requirement":103,"action":"auth_users_list","kind":"sdk","is_mutation":false,"requires_grant":true,"requires_cost_approval":false,"sensitive":true,"permission_scope":"infrastructure:read","input_schema":{"type":"object","properties":{"tenant_id":{"type":"string","format":"uuid"},"offset":{"type":"integer","minimum":0,"maximum":10000},"limit":{"type":"integer","minimum":1,"maximum":20}},"required":["tenant_id"],"additionalProperties":false},"result_schema":{"type":"object","properties":{"users":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid"},"email":{"type":["string","null"],"maxLength":400},"created_at":{"type":["string","null"],"maxLength":400},"updated_at":{"type":["string","null"],"maxLength":400},"email_confirmed_at":{"type":["string","null"],"maxLength":400},"last_sign_in_at":{"type":["string","null"],"maxLength":400},"banned_until":{"type":["string","null"],"maxLength":400},"deleted_at":{"type":["string","null"],"maxLength":400}},"required":["id","email","created_at","updated_at","email_confirmed_at","last_sign_in_at","banned_until","deleted_at"],"additionalProperties":false},"maxItems":100},"next_offset":{"type":["integer","null"],"minimum":0}},"required":["users","next_offset"],"additionalProperties":false},"description":"Tenant-consented fixed-project auth_users_list through the pinned official Supabase SDK and scoped service RPCs.","output_schema":{"type":"object","properties":{"ok":{"const":true},"operation":{"const":"supabase.auth.users.list"},"contract_version":{"const":"1.0.0"},"executed":{"const":true},"request_state":{"enum":["accepted","observed"]},"admission_id":{"type":"string","format":"uuid"},"result":{"type":"object","properties":{"users":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid"},"email":{"type":["string","null"],"maxLength":400},"created_at":{"type":["string","null"],"maxLength":400},